Theorem grow1 : PMA.opnew_spec L ar HI -> forall (fx : FPState) R M model K LBX FF LK Aw cr v b k stk sp r p1 p2 p3 m n t,
    ri_inv HI (PM.vec_own b k ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
