    getr R (reg 11) = Z_to_bv 64 p1 -> getr R (reg 12) = Z_to_bv 64 p2 -> getr R (reg 13) = Z_to_bv 64 p3 -> p1 mod 4 = 0 -> p2 mod 8 = 0 ->
